<template><div class="art-full-height"><ElCard class="mb-3"><ElForm inline><ElFormItem label="审核状态"><ElSelect v-model="query.status" clearable class="!w-40"><ElOption label="待审核" value="PENDING_REVIEW"/><ElOption label="已完成" value="COMPLETED"/><ElOption label="已驳回" value="REJECTED"/></ElSelect></ElFormItem><ElFormItem><ElButton type="primary" @click="load">查询</ElButton></ElFormItem></ElForm></ElCard><ElCard><ElTable v-loading="loading" :data="rows"><ElTableColumn prop="orderNo" label="订单号" min-width="190"/><ElTableColumn prop="playerName" label="陪玩师" width="130"/><ElTableColumn prop="productName" label="商品" min-width="160"/><ElTableColumn prop="completionNote" label="完成说明" min-width="200" show-overflow-tooltip/><ElTableColumn prop="submittedAt" label="提交时间" width="180"/><ElTableColumn label="状态" width="100"><template #default="{row}"><ElTag>{{statusText(row.fulfillmentStatus)}}</ElTag></template></ElTableColumn><ElTableColumn label="操作" width="90"><template #default="{row}"><ElButton link type="primary" @click="open(row)">查看</ElButton></template></ElTableColumn></ElTable><div class="flex justify-end mt-4"><ElPagination v-model:current-page="query.current" :total="total" @change="load" layout="total,prev,pager,next"/></div></ElCard><ElDrawer v-model="visible" title="履约凭证审核" size="620px"><template v-if="detail"><ElDescriptions :column="2" border><ElDescriptionsItem label="订单号">{{detail.orderNo}}</ElDescriptionsItem><ElDescriptionsItem label="陪玩师">{{detail.playerName}}</ElDescriptionsItem><ElDescriptionsItem label="完成数量">{{detail.actualQuantity||'-'}}</ElDescriptionsItem><ElDescriptionsItem label="提交时间">{{detail.submittedAt}}</ElDescriptionsItem><ElDescriptionsItem label="完成说明" :span="2">{{detail.completionNote}}</ElDescriptionsItem></ElDescriptions><h4>完成凭证</h4><ElImage v-for="url in detail.proofUrls" :key="url" :src="url" :preview-src-list="detail.proofUrls" fit="cover" class="proof"/><div v-if="detail.fulfillmentStatus==='PENDING_REVIEW'" class="mt-5"><ElButton type="success" @click="review('APPROVE')">审核通过</ElButton><ElButton type="danger" @click="review('REJECT')">驳回</ElButton></div><ElAlert v-if="detail.reviewRemark" class="mt-4" :title="detail.reviewRemark" type="info" :closable="false"/></template></ElDrawer></div></template>
<script setup lang="ts">import{fetchFulfillments,fetchFulfillment,reviewFulfillment}from'@/api/business-manage';const loading=ref(false),rows=ref<any[]>([]),total=ref(0),visible=ref(false),detail=ref<any>(),query=reactive({current:1,size:20,status:'PENDING_REVIEW'});async function load(){loading.value=true;try{const d=await fetchFulfillments(query);rows.value=d.records;total.value=d.total}finally{loading.value=false}}async function open(r:any){detail.value=await fetchFulfillment(r.id);visible.value=true}async function review(action:string){let remark='';if(action==='REJECT')remark=await ElMessageBox.prompt('请输入驳回原因','驳回凭证',{inputValidator:v=>Boolean(v)||'请输入驳回原因'}).then(x=>x.value);else await ElMessageBox.confirm('确认该订单已履约完成吗？','审核确认');await reviewFulfillment(detail.value.id,action,remark);ElMessage.success('处理成功');visible.value=false;load()}const statusText=(s:string)=>({PENDING_REVIEW:'待审核',COMPLETED:'已完成',REJECTED:'已驳回',IN_SERVICE:'服务中'}[s]||s);onMounted(load)</script><style scoped>.proof{width:120px;height:120px;margin:0 12px 12px 0;border-radius:8px}</style>
